1	/**
2	 * Shared TypeScript contracts for Restaurant Arena (restaurant-arena/v1).
3	 * Aligns field-for-field with docs/restaurant-arena-state-contract.md,
4	 * docs/restaurant-arena-tools.md, and retro-backend/esim/contracts.py.
5	 */
6	
7	export const STATE_VERSION = "restaurant-arena/v1" as const;
8	// v2 adds the message inbox v1 had no field for; see DeliveredMessage.
9	// v1 stays published and readable: a v1 observation is a v2 observation with
10	// an empty inbox and an older version string.
11	export const OBSERVATION_VERSION = "restaurant-arena-observation/v2" as const;
12	export const OBSERVATION_VERSION_V1 = "restaurant-arena-observation/v1" as const;
13	export const ACTION_VERSION = "restaurant-arena-action/v1" as const;
14	export const TRACE_VERSION = "restaurant-arena-trace/v1" as const;
15	
16	export type Role = "host" | "supply_lead" | "chef" | "server";
17	
18	/** Historical worker role identifier preserved for backward compatibility with old traces. */
19	export type LegacyRole = "expediter";
20	export type HistoricalRole = Role | LegacyRole;
21	
22	export type OrderStatus =
23	  | "queued"
24	  | "seated"
25	  | "preparing"
26	  | "ready"
27	  | "served"
28	  | "cancelled";
29	
30	export type Priority = "normal" | "high";
31	
32	export type TableStatus = "empty" | "occupied";
33	
34	export type EquipmentKind = "oven" | "warming_shelf";
35	
36	export type EquipmentStatus = "working" | "failed" | "degraded";
37	
38	export type WorkerLocation = "floor" | "kitchen" | "pass" | "queue";
39	
40	export type EpisodePhase = "active" | "complete";
41	
42	export type ActorType = "worker" | "player";
43	
44	export type Tool =
45	  | "inspect"
46	  | "prepare"
47	  | "serve"
48	  | "seat"
49	  | "update_guest"
50	  | "coordinate"
51	  | "request_help"
52	  | "send_message"
53	  // Player-only tools: never granted to a worker role in ROLE_PERMISSIONS.
54	  // The human manager overrules the floor through the same validated
55	  // envelope boundary rather than a separate, unchecked control surface.
56	  | "approve"
57	  | "correct";
58	
59	export type ActionErrorCode =
60	  | "role_not_permitted"
61	  | "invalid_arguments"
62	  | "unknown_entity"
63	  | "invalid_state"
64	  | "stale_tick"
65	  | "duplicate_request"
66	  | "unsafe_action"
67	  | "episode_complete"
68	  /** The open round's manager envelope is already spent (#262). */
69	  | "round_budget_exhausted";
70	
71	export interface Episode {
72	  id: string;
73	  phase: EpisodePhase;
74	  tick: number;
75	  maxTicks: number;
76	}
77	
78	export interface Clock {
79	  minute: number;
80	  speed: number;
81	}
82	
83	export interface Table {
84	  id: string;
85	  seats: number;
86	  status: TableStatus;
87	  orderId?: string;
88	}
89	
90	export interface Order {
91	  id: string;
92	  tableId?: string;
93	  items: string[];
94	  status: OrderStatus;
95	  allergy?: string;
96	  priority: Priority;
97	}
98	
99	export interface EquipmentItem {
100	  id: string;
101	  kind: EquipmentKind;
102	  status: EquipmentStatus;
103	  safetyThreshold?: number;
104	  reading?: number;
105	}
106	
107	export interface WorkerState {
108	  id: string;
109	  role: Role;
110	  load: number;
111	  location: WorkerLocation;
112	  lastAction?: string;
113	}
114	
115	export interface Emergency {
116	  kind: "oven_failure";
117	  active: boolean;
118	  startedAt: number;
119	}
120	
121	export interface Outcomes {
122	  cash: number;
123	  satisfaction: number;
124	  waste: number;
125	  waitTime: number;
126	  completed: number;
127	  safeOrders: number;
128	  coordination: number;
129	  correctionUptake: number;
130	}
131	
132	export interface RestaurantState {
133	  version: typeof STATE_VERSION;
134	  seed: number;
135	  episode: Episode;
136	  clock: Clock;
137	  tables: Table[];
138	  orders: Order[];
139	  inventory: Record<string, number>;
140	  equipment: EquipmentItem[];
141	  workers: WorkerState[];
142	  emergency?: Emergency;
143	  /** Host is holding the door: no new parties are seated until it clears. */
144	  seatingHeld?: boolean;
145	  reputation: number;
146	  outcomes: Outcomes;
147	}
148	
149	export interface ActionEnvelope {
150	  version: typeof ACTION_VERSION;
151	  episodeId: string;
152	  actorId: string;
153	  actorType: ActorType;
154	  role: Role;
155	  tool: Tool;
156	  arguments: Record<string, unknown>;
157	  tick: number;
158	  timestamp: string;
159	  requestId: string;
160	  idempotencyKey: string;
161	}
162	
163	export interface ActionError {
164	  code: ActionErrorCode;
165	  message: string;
166	  retryable: boolean;
167	}
168	
169	export interface ActionSuccess {
170	  accepted: true;
171	  tick: number;
172	  state: RestaurantState;
173	}
174	
175	export type ActionResult =
176	  | ActionSuccess
177	  | { accepted: false; error: ActionError };
178	
179	// --- Observation Projections ---
180	
181	export interface ObservedOrder {
182	  id: string;
183	  items: string[];
184	  allergy?: string;
185	  priority: Priority;
186	}
187	
188	export interface ObservedEquipment {
189	  id: string;
190	  status: EquipmentStatus;
191	  /**
192	   * Measured temperature in °C, when the device has a sensor. Paired with
193	   * `safetyThreshold` so a role can tell a device that is merely degraded
194	   * from one that has crossed a food-safety limit, instead of inferring
195	   * severity from the word "overheat".
196	   */
197	  reading?: number;
198	  /** The food-safety limit in °C. At or above it, the fault is a safety failure. */
199	  safetyThreshold?: number;
200	}
201	
202	/**
203	 * One `send_message` delivery, as its recipient sees it. Carries
204	 * `sentAtTick` rather than a timestamp: the simulator has no wall clock, and
205	 * the tick is what a recipient needs to tell a fresh message from a stale
206	 * one. Visible on the observation for the tick after it was sent, and on
207	 * that tick only.
208	 */
209	export interface DeliveredMessage {
210	  from: string;
211	  text: string;
212	  priority: Priority;
213	  sentAtTick: number;
214	}
215	
216	export interface ChefObservation {
217	  version: typeof OBSERVATION_VERSION;
218	  role: "chef";
219	  tick: number;
220	  load: number;
221	  orders: ObservedOrder[];
222	  inventory: Record<string, number>;
223	  equipment: ObservedEquipment[];
224	  messages?: DeliveredMessage[];
225	}
226	
227	export interface ObservedTable {
228	  id: string;
229	  orderId?: string;
230	  status: OrderStatus;
231	  waitMinutes: number;
232	}
233	
234	export interface GuestConstraint {
235	  orderId: string;
236	  kind: "allergy" | "dietary" | "timing";
237	  value?: string;
238	}
239	
240	export interface ServerObservation {
241	  version: typeof OBSERVATION_VERSION;
242	  role: "server";
243	  tick: number;
244	  load: number;
245	  tables: ObservedTable[];
246	  guestConstraints: GuestConstraint[];
247	  messages?: DeliveredMessage[];
248	}
249	
250	export interface QueuedParty {
251	  partyId: string;
252	  size: number;
253	  waitMinutes: number;
254	}
255	
256	export interface AvailableTable {
257	  id: string;
258	  seats: number;
259	  status: "empty";
260	}
261	
262	export interface HostObservation {
263	  version: typeof OBSERVATION_VERSION;
264	  role: "host";
265	  tick: number;
266	  load: number;
267	  queue: QueuedParty[];
268	  tables: AvailableTable[];
269	  waitEstimateMinutes: number;
270	  messages?: DeliveredMessage[];
271	}
272	
273	export interface HandoffOrder {
274	  id: string;
275	  status: OrderStatus;
276	  priority: Priority;
277	  handoff: string;
278	}
279	
280	export interface ObservedWorker {
281	  id: string;
282	  role: Role;
283	  load: number;
284	}
285	
286	export interface ObservedIncident {
287	  kind: "oven_failure" | "warming_shelf_overheat";
288	  active: boolean;
289	  /**
290	   * Whether the incident crosses a safety limit. `non_safety` incidents are
291	   * operational: adapt or work around them, do not halt service. Optional so
292	   * an observation recorded before the field existed still type-checks.
293	   */
294	  severity?: IncidentSeverity;
295	}
296	
297	export type IncidentSeverity = "safety_critical" | "non_safety";
298	
299	export interface SupplyLeadObservation {
300	  version: typeof OBSERVATION_VERSION;
301	  role: "supply_lead";
302	  tick: number;
303	  load: number;
304	  orders: HandoffOrder[];
305	  workers: ObservedWorker[];
306	  incidents: ObservedIncident[];
307	  messages?: DeliveredMessage[];
308	}
309	
310	/** Historical observation contract preserved for reading old traces. */
311	export interface LegacyExpediterObservation {
312	  version: typeof OBSERVATION_VERSION | typeof OBSERVATION_VERSION_V1;
313	  role: "expediter";
314	  tick: number;
315	  load: number;
316	  orders: HandoffOrder[];
317	  workers: ObservedWorker[];
318	  incidents: ObservedIncident[];
319	  messages?: DeliveredMessage[];
320	}
321	
322	export type ExpediterObservation = SupplyLeadObservation | LegacyExpediterObservation;
323	
324	export type Observation =
325	  | ChefObservation
326	  | ServerObservation
327	  | HostObservation
328	  | SupplyLeadObservation
329	  | LegacyExpediterObservation;
330	
331	// --- Runtime Type Guards & Validators ---
332	
333	export function isRestaurantState(data: unknown): data is RestaurantState {
334	  if (typeof data !== "object" || data === null) return false;
335	  const s = data as Record<string, unknown>;
336	
337	  if (s.version !== STATE_VERSION) return false;
338	  if (typeof s.seed !== "number" || !Number.isInteger(s.seed)) return false;
339	
340	  // episode
341	  if (typeof s.episode !== "object" || s.episode === null) return false;
342	  const ep = s.episode as Record<string, unknown>;
343	  if (typeof ep.id !== "string" || !ep.id) return false;
344	  if (ep.phase !== "active" && ep.phase !== "complete") return false;
345	  if (typeof ep.tick !== "number" || ep.tick < 0) return false;
346	  if (typeof ep.maxTicks !== "number" || ep.maxTicks < 1) return false;
347	
348	  // clock
349	  if (typeof s.clock !== "object" || s.clock === null) return false;
350	  const clk = s.clock as Record<string, unknown>;
351	  if (typeof clk.minute !== "number" || clk.minute < 0) return false;
352	  if (typeof clk.speed !== "number" || clk.speed < 1) return false;
353	
354	  // tables
355	  if (!Array.isArray(s.tables)) return false;
356	  for (const t of s.tables) {
357	    if (typeof t !== "object" || t === null) return false;
358	    if (typeof t.id !== "string" || typeof t.seats !== "number") return false;
359	    if (t.status !== "empty" && t.status !== "occupied") return false;
360	  }
361	
362	  // orders
363	  if (!Array.isArray(s.orders)) return false;
364	  const validStatuses = new Set([
365	    "queued",
366	    "seated",
367	    "preparing",
368	    "ready",
369	    "served",
370	    "cancelled",
371	  ]);
372	  for (const o of s.orders) {
373	    if (typeof o !== "object" || o === null) return false;
374	    if (typeof o.id !== "string" || !Array.isArray(o.items)) return false;
375	    if (!validStatuses.has(o.status)) return false;
376	    if (o.priority !== "normal" && o.priority !== "high") return false;
377	  }
378	
379	  // inventory
380	  if (typeof s.inventory !== "object" || s.inventory === null) return false;
381	  for (const [k, v] of Object.entries(s.inventory)) {
382	    if (typeof k !== "string" || typeof v !== "number" || v < 0) return false;
383	  }
384	
385	  // equipment
386	  if (!Array.isArray(s.equipment)) return false;
387	  const validEquipKinds = new Set(["oven", "warming_shelf"]);
388	  const validEquipStatuses = new Set(["working", "failed", "degraded"]);
389	  for (const eq of s.equipment) {
390	    if (typeof eq !== "object" || eq === null) return false;
391	    if (typeof eq.id !== "string") return false;
392	    if (!validEquipKinds.has(eq.kind) || !validEquipStatuses.has(eq.status)) return false;
393	  }
394	
395	  // workers
396	  if (!Array.isArray(s.workers)) return false;
397	  const validRoles = new Set(["host", "supply_lead", "chef", "server", "expediter"]);
398	  const validLocations = new Set(["floor", "kitchen", "pass", "queue"]);
399	  for (const w of s.workers) {
400	    if (typeof w !== "object" || w === null) return false;
401	    if (typeof w.id !== "string") return false;
402	    if (!validRoles.has(w.role) || !validLocations.has(w.location)) return false;
403	    if (typeof w.load !== "number" || w.load < 0 || w.load > 1) return false;
404	  }
405	
406	  // reputation
407	  if (typeof s.reputation !== "number" || s.reputation < 0 || s.reputation > 100) return false;
408	
409	  // outcomes
410	  if (typeof s.outcomes !== "object" || s.outcomes === null) return false;
411	  const out = s.outcomes as Record<string, unknown>;
412	  const reqOutcomes = [
413	    "cash",
414	    "satisfaction",
415	    "waste",
416	    "waitTime",
417	    "completed",
418	    "safeOrders",
419	    "coordination",
420	    "correctionUptake",
421	  ];
422	  for (const key of reqOutcomes) {
423	    if (typeof out[key] !== "number") return false;
424	  }
425	
426	  // optional emergency
427	  if (s.emergency !== undefined && s.emergency !== null) {
428	    const em = s.emergency as Record<string, unknown>;
429	    if (em.kind !== "oven_failure") return false;
430	    if (typeof em.active !== "boolean" || typeof em.startedAt !== "number") return false;
431	  }
432	
433	  return true;
434	}
435	
436	export function isValidRole(role: unknown): role is Role {
437	  const validRoles = new Set(["host", "supply_lead", "chef", "server"]);
438	  return typeof role === "string" && validRoles.has(role);
439	}
440	
441	export function isActionEnvelope(data: unknown): data is ActionEnvelope {
442	  if (typeof data !== "object" || data === null) return false;
443	  const a = data as Record<string, unknown>;
444	
445	  if (a.version !== ACTION_VERSION) return false;
446	  if (typeof a.episodeId !== "string" || !a.episodeId) return false;
447	  if (typeof a.actorId !== "string" || !a.actorId) return false;
448	  if (a.actorType !== "worker" && a.actorType !== "player") return false;
449	  if (a.role !== "host" && a.role !== "supply_lead" && a.role !== "chef" && a.role !== "server" && a.role !== "expediter") return false;
450	  if (typeof a.tool !== "string" || !a.tool) return false;
451	  if (typeof a.arguments !== "object" || a.arguments === null) return false;
452	  if (typeof a.tick !== "number" || a.tick < 0) return false;
453	  if (typeof a.timestamp !== "string" || !a.timestamp) return false;
454	  if (typeof a.requestId !== "string" || !a.requestId) return false;
455	  if (typeof a.idempotencyKey !== "string" || !a.idempotencyKey) return false;
456	
457	  return true;
458	}
