ger overrules the floor through the same validated\n  // envelope boundary rather than a separate, unchecked control surface.\n  | \"approve\"\n  | \"correct\";\n\nexport type ActionErrorCode =\n  | \"role_not_permitted\"\n  | \"invalid_arguments\"\n  | \"unknown_entity\"\n  | \"invalid_state\"\n  | \"stale_tick\"\n  | \"duplicate_request\"\n  | \"unsafe_action\"\n  | \"episode_complete\"\n  /** The open round's manager envelope is already spent (#262). */\n  | \"round_budget_exhausted\";\n\nexport interface Episode {\n  id: string;\n  phase: EpisodePhase;\n  tick: number;\n  maxTicks: number;\n}\n\nexport interface Clock {\n  minute: number;\n  speed: number;\n}\n\nexport interface Table {\n  id: string;\n  seats: number;\n  status: TableStatus;\n  orderId?: string;\n}\n\nexport interface Order {\n  id: string;\n  tableId?: string;\n  items: string[];\n  status: OrderStatus;\n  allergy?: string;\n  priority: Priority;\n}\n\nexport interface EquipmentItem {\n  id: string;\n  kind: EquipmentKind;\n  status: EquipmentStatus;\n  safetyThreshold?: number;\n  reading?: number;\n}\n\nexport interface WorkerState {\n  id: string;\n  role: Role;\n  load: number;\n  location: WorkerLocation;\n  lastAction?: string;\n}\n\nexport interface Emergency {\n  kind: \"oven_failure\";\n  active: boolean;\n  startedAt: number;\n}\n\nexport interface Outcomes {\n  cash: number;\n  satisfaction: number;\n  waste: number;\n  waitTime: number;\n  completed: number;\n  safeOrders: number;\n  coordination: number;\n  correctionUptake: number;\n}\n\nexport interface RestaurantState {\n  version: typeof STATE_VERSION;\n  seed: number;\n  episode: Episode;\n  clock: Clock;\n  tables: Table[];\n  orders: Order[];\n  inventory: Record<string, number>;\n  equipment: EquipmentItem[];\n  workers: WorkerState[];\n  emergency?: Emergency;\n  /** Host is holding the door: no new parties are seated until it clears. */\n  seatingHeld?: boolean;\n  reputation: number;\n  outcomes: Outcomes;\n}\n\nexport interface ActionEnvelope {\n  version: typeof ACTION_VERSION;\n  episodeId: string;\n  actorId: string;\n  actorType: ActorType;\n  role: Role;\n  tool: Tool;\n  arguments: Record<string, unknown>;\n  tick: number;\n  timestamp: string;\n  requestId: string;\n  idempotencyKey: string;\n}\n\nexport interface ActionError {\n  code: ActionErrorCode;\n  message: string;\n  retryable: boolean;\n}\n\nexport interface ActionSuccess {\n  accepted: true;\n  tick: number;\n  state: RestaurantState;\n}\n\nexport type ActionResult =\n  | ActionSuccess\n  | { accepted: false; error: ActionError };\n\n// --- Observation Projections ---\n\nexport interface ObservedOrder {\n  id: string;\n  items: string[];\n  allergy?: string;\n  priority: Priority;\n}\n\nexport interface ObservedEquipment {\n  id: string;\n  status: EquipmentStatus;\n  /**\n   * Measured temperature in °C, when the device has a sensor. Paired with\n   * `safetyThreshold` so a role can tell a device that is merely degraded\n   * from one that has crossed a food-safety limit, instead of inferring\n   * severity from the word \"overheat\".\n   */\n  reading?: number;\n  /** The food-safety limit in °C. At or above it, the fault is a safety failure. */\n  safetyThreshold?: number;\n}\n\n/**\n * One `send_message` delivery, as its recipient sees it. Carries\n * `sentAtTick` rather than a timestamp: the simulator has no wall clock, and\n * the tick is what a recipient needs to tell a fresh message from a stale\n * one. Visible on the observation for the tick after it was sent, and on\n * that tick only.\n */\nexport interface DeliveredMessage {\n  from: string;\n  text: string;\n  priority: Priority;\n  sentAtTick: number;\n}\n\nexport interface ChefObservation {\n  version: typeof OBSERVATION_VERSION;\n  role: \"chef\";\n  tick: number;\n  load: number;\n  orders: ObservedOrder[];\n  inventory: Record<string, number>;\n  equipment: ObservedEquipment[];\n  messages?: DeliveredMessage[];\n}\n\nexport interface ObservedT