537	  private applyDecision(decisionId: string, optionId: string): boolean {
538	    const decision = DECISIONS_BY_ID.get(decisionId);
539	    const option = decision?.options.find((o) => o.id === optionId);
540	    if (!decision || !option || this.openDecision?.id !== decisionId) return false;
541	
542	    this.openDecision = undefined;
543	    this.decisionsTaken.push({ decisionId, optionId });
544	    this.log("you", "player", option.label);
545	    const out = this.currentState.outcomes;
546	    // A short, concrete receipt for the on-canvas callout — what changed,
547	    // not why. The service log still carries the flavour line; this is
548	    // the version the player can read without looking away from the spot
549	    // the decision card just vacated.
