714	        headline = "Served anyway — reputation hit";
715	        const serveHash = computeStateHash({ episodeId, action: "shelf_serve", tick: currentTick });
716	        this.recordEvent({
717	          tick: currentTick,
718	          kind: "action",
719	          timestamp: this.timestampForTick(currentTick),
720	          stateHash: serveHash,
721	          actorId: "player",
722	          text: "Player served plates from overheated warming shelf.",
