1321	        // assign_<role>_<location>: the player moved a worker across the floor.
1322	        const assign = /^assign_(host|supply_lead|chef|server|expediter)_(kitchen|pass|floor|queue)$/.exec(action);
1323	        if (assign) {
1324	          const rawRole = assign[1];
1325	          const role = (rawRole === "expediter" ? "supply_lead" : rawRole) as Role;
1326	          const worker = this.currentState.workers.find((w) => w.role === role || (w.role as string) === rawRole);
1327	          if (worker && worker.location !== assign[2]) {
1328	            worker.location = assign[2] as WorkerLocation;
1329	            worker.lastAction = `move:${assign[2]}`;
1330	            this.log("you", "player", `Moved ${STAFF[role].name} to the ${assign[2]}.`);
1331	            moved = true;
1332	          }
1333	        }
1334	        break;
