1372	  private advanceWorld(): RestaurantState {
1373	    if (this.isOver()) return this.state();
1374	
1375	    const nextTick = this.currentState.episode.tick + 1;
1376	
1377	    // 0. Rotate the message inbox: what was pending (sent this tick) becomes
1378	    // visible for exactly the next tick, then is dropped.
1379	    this.inbox = this.pendingInbox;
1380	    this.pendingInbox = new Map();
1381	
1382	    // The clock moves first so everything logged this tick is stamped with
1383	    // the time it actually happened.
1384	    this.currentState.episode.tick = nextTick;
1385	    this.currentState.clock.minute += this.currentState.clock.speed;
1386	
1387	    // 1. Scheduled Incidents
1388	    for (const incident of this.preset.incidents) {
1389	      if (incident.tick === nextTick) {
1390	        if (incident.kind === "oven_failure") {
1391	          const oven = this.currentState.equipment.find((e) => e.id === incident.targetId);
1392	          if (oven) oven.status = "failed";
1393	          this.currentState.emergency = {
1394	            kind: "oven_failure",
1395	            active: true,
1396	            startedAt: nextTick,
1397	          };
1398	          const incidentEventId = `evt-dec-allergy-${this.currentState.seed}`;
1399	          const episodeId = this.currentState.episode.id || `dinner-rush-${this.currentState.seed}`;
1400	          const incidentHash = computeStateHash({ episodeId, incident: "oven_failure_and_allergy", tick: nextTick });
1401	          this.recordEvent({
1402	            tick: nextTick,
1403	            kind: "observation",
1404	            timestamp: this.timestampForTick(nextTick),
1405	            stateHash: incidentHash,
1406	            actorId: "system",
1407	            requestId: incidentEventId,
1408	            subject: {
1409	              kind: "equipment",
1410	              id: incident.targetId,
1411	            },
1412	            text: "Oven-1 failure occurred; peanut allergy constraint on Table 2 ticket requires verification.",
1413	            observation: {
1414	              emergency: { kind: "oven_failure", active: true },
1415	              orderId: "order-2",
1416	              allergy: "peanut",
1417	            },
1418	          });
1419	        } else if (incident.kind === "warming_shelf_overheat") {
1420	          const shelf = this.currentState.equipment.find((e) => e.id === incident.targetId);
1421	          if (shelf && shelf.safetyThreshold !== undefined) {
1422	            shelf.status = "degraded";
1423	            shelf.reading = Math.min(shelf.safetyThreshold - 1, (shelf.reading || 62) + 6);
1424	          }
1425	          this.log(
