1466	    }
1467	
1468	    // 6. Incident beats put the call in the player's hands.
1469	    if (this.currentState.emergency?.active && this.currentState.emergency.kind === "oven_failure") {
1470	      this.raiseDecision("oven_down");
1471	    }
