485	  private log(voice: FeedVoice, kind: FeedKind, text: string): void {
486	    const who =
487	      voice === "house" ? "The Little Plate" : voice === "you" ? "You" : STAFF[voice].name;
488	    this.feed.push({
489	      id: this.feedId++,
490	      tick: this.currentState.episode.tick,
491	      clock: this.clockLabel(),
492	      who,
493	      voice,
494	      kind,
495	      text,
496	    });
497	    // The rail only ever shows the tail; keeping the whole shift would grow
498	    // without bound across a long episode.
499	    if (this.feed.length > 120) this.feed = this.feed.slice(-120);
500	  }
