1718	  private adaptLegacyActionEnvelope(envelope: ActionEnvelope): ActionEnvelope {
1719	    const isLegacyRole = (envelope.role as string) === "expediter";
1720	    const isLegacyActor = envelope.actorId === "worker-expediter";
1721	    const isLegacyTarget = envelope.tool === "send_message" && envelope.arguments?.to === "worker-expediter";
1722	    const isLegacyTargetRole = envelope.arguments?.targetRole === "expediter";
1723	    const isLegacyWorkerId = envelope.arguments?.workerId === "worker-expediter" || envelope.arguments?.workerId === "expediter";
1724	
1725	    if (!isLegacyRole && !isLegacyActor && !isLegacyTarget && !isLegacyTargetRole && !isLegacyWorkerId) {
1726	      return envelope;
1727	    }
1728	
1729	    const role: Role = isLegacyRole ? "supply_lead" : (envelope.role as Role);
1730	    const actorId = isLegacyActor ? "worker-supply_lead" : envelope.actorId;
1731	    let args = envelope.arguments;
1732	    if (isLegacyTarget || isLegacyTargetRole || isLegacyWorkerId) {
1733	      args = { ...args };
1734	      if (args.to === "worker-expediter") args.to = "worker-supply_lead";
1735	      if (args.targetRole === "expediter") args.targetRole = "supply_lead";
1736	      if (args.workerId === "worker-expediter" || args.workerId === "expediter") {
1737	        args.workerId = "worker-supply_lead";
1738	      }
1739	    }
1740	
1741	    return {
1742	      ...envelope,
1743	      role,
1744	      actorId,
1745	      arguments: args,
1746	    };
1747	  }
