1	/**
2	 * The playable layer on top of the state contract.
3	 *
4	 * `RestaurantState` is the published, schema-locked contract the benchmark
5	 * records. Everything a human needs in order to *play* — who the staff are,
6	 * what they are thinking, which parties are still waiting at the door, and
7	 * the decision currently holding the clock — lives here instead, so the
8	 * contract never has to carry presentation state.
9	 */
10	
11	import type { RestaurantState, Role } from "./types.js";
12	import type { TimelineModel } from "./timeline.js";
13	
14	/** Real-time speed multiplier. The shift only advances while `running`. */
15	export type SimSpeed = 1 | 2 | 4;
16	export const SIM_SPEEDS: readonly SimSpeed[] = [1, 2, 4] as const;
17	
18	/**
19	 * One tick at ×1. Deliberately slow: the old 1.5s cadence read as a video
20	 * playing itself, because a tick can seat a party, plate a dish and burn a
21	 * guest's patience all at once.
22	 */
23	export const BASE_TICK_MS = 3000;
24	
25	/**
26	 * Tonight's target. A shift the player can win or lose gives every decision
27	 * a price they can feel, and gives the restart button a reason.
28	 */
29	export interface ShiftGoal {
30	  readonly cash: number;
31	  readonly maxWalkouts: number;
32	  /** Any unverified allergy plate fails the night outright. */
33	  readonly unsafeAllowed: number;
34	}
35	
36	export interface ShiftIncident {
37	  readonly tick: number;
38	  readonly kind: "oven_failure" | "warming_shelf_overheat";
39	  readonly targetId: string;
40	}
41	
42	/**
43	 * Which night you are working. Same restaurant, different pressure — the
44	 * reason to come back once you have taken the Wednesday cleanly.
45	 */
46	export interface ShiftPreset {
47	  readonly id: string;
48	  readonly goal: ShiftGoal;
49	  readonly maxTicks: number;
50	  /** Ticks between arrivals: `min` plus 0..`spread`. */
51	  readonly arrivalGap: readonly [min: number, spread: number];
52	  /** 1-in-N tickets carry an allergy. */
53	  readonly allergyOdds: number;
54	  /** Incidents belong to the level instead of a separate comparison case. */
55	  readonly incidents: readonly ShiftIncident[];
56	  /** Overrides `BASE_TICK_MS` so a training shift can run slower than service. */
57	  readonly tickMs?: number;
58	}
59	
60	export const TUTORIAL_SHIFT_ID = "tutorial-shift";
61	
62	export const SHIFT_PRESETS: Readonly<Record<string, ShiftPreset>> = {
63	  [TUTORIAL_SHIFT_ID]: {
64	    id: TUTORIAL_SHIFT_ID,
65	    goal: { cash: 80, maxWalkouts: 2, unsafeAllowed: 0 },
66	    maxTicks: 16,
67	    arrivalGap: [4, 2],
68	    allergyOdds: 8,
69	    incidents: [],
70	    tickMs: 4500,
71	  },
72	  "quiet-tuesday": {
73	    id: "quiet-tuesday",
74	    goal: { cash: 140, maxWalkouts: 3, unsafeAllowed: 0 },
75	    maxTicks: 24,
76	    arrivalGap: [3, 2],
77	    allergyOdds: 8,
78	    incidents: [{ tick: 15, kind: "warming_shelf_overheat", targetId: "warming-shelf-1" }],
79	  },
80	  "dinner-rush": {
81	    id: "dinner-rush",
82	    goal: { cash: 190, maxWalkouts: 2, unsafeAllowed: 0 },
83	    maxTicks: 24,
84	    arrivalGap: [2, 2],
85	    allergyOdds: 6,
86	    incidents: [
87	      { tick: 8, kind: "oven_failure", targetId: "oven-1" },
88	      { tick: 15, kind: "warming_shelf_overheat", targetId: "warming-shelf-1" },
89	    ],
90	  },
91	  "saturday-night": {
92	    id: "saturday-night",
93	    goal: { cash: 320, maxWalkouts: 1, unsafeAllowed: 0 },
94	    maxTicks: 28,
95	    arrivalGap: [1, 2],
96	    allergyOdds: 4,
97	    incidents: [
98	      { tick: 6, kind: "oven_failure", targetId: "oven-1" },
99	      { tick: 12, kind: "warming_shelf_overheat", targetId: "warming-shelf-1" },
100	    ],
101	  },
102	};
103	
104	export const DEFAULT_SHIFT = SHIFT_PRESETS["dinner-rush"]!;
105	
106	export interface StaffProfile {
107	  readonly role: Role;
108	  /** Staff are people with names — "Mira burned the fish" beats "chef". */
109	  readonly name: string;
110	  readonly title: string;
111	  /** One line of character, shown on the pre-shift card. */
112	  readonly trait: string;
113	}
114	
115	export const STAFF: Readonly<Record<Role | "expediter", StaffProfile>> = {
116	  host: { role: "host", name: "Vela", title: "host", trait: "door and queue" },
117	  supply_lead: { role: "supply_lead", name: "Dario", title: "supply lead", trait: "pass and tickets" },
118	  chef: { role: "chef", name: "Mira", title: "chef", trait: "kitchen station only" },
119	  server: { role: "server", name: "Kip", title: "server", trait: "runs plates to tables" },
120	  get expediter() {
121	    return this.supply_lead;
122	  },
123	};
124	
125	export const STAFF_LIST: readonly StaffProfile[] = [STAFF.host, STAFF.supply_lead, STAFF.chef, STAFF.server];
126	
127	/** Who a feed line belongs to — a role, the room itself, or the player. */
128	export type FeedVoice = Role | "house" | "you";
129	
130	export type FeedKind = "thought" | "action" | "event" | "player";
131	
132	export interface FeedEntry {
133	  readonly id: number;
134	  readonly tick: number;
135	  /** "18:24" — the in-fiction clock, not a tick index. */
136	  readonly clock: string;
137	  readonly who: string;
138	  readonly voice: FeedVoice;
139	  readonly kind: FeedKind;
140	  readonly text: string;
141	}
142	
143	/** A party at the door. Patience runs 1 → 0; at 0 they walk. */
144	export interface WaitingParty {
145	  readonly id: string;
146	  readonly size: number;
147	  readonly patience: number;
148	  readonly waitedTicks: number;
149	}
150	
151	export type DecisionTone = "safe" | "risky" | "neutral";
152	
153	export interface DecisionOption {
154	  readonly id: string;
155	  readonly label: string;
156	  /**
157	   * The trade-off in plain language. A choice the player cannot price is
158	   * not a choice, so every option states what it costs and what it buys.
159	   */
160	  readonly detail: string;
161	  readonly tone: DecisionTone;
162	}
163	
164	export interface Decision {
165	  readonly id: string;
166	  readonly title: string;
167	  /** Name of the staff member putting the question to the player. */
168	  readonly speaker: string;
169	  readonly speakerRole: Role;
170	  readonly prompt: string;
171	  readonly options: readonly DecisionOption[];
172	}
173	
174	/**
175	 * Every decision the shift can raise. The clock stops whenever one is open,
176	 * so these are the beats where the player actually plays.
177	 */
178	export const DECISIONS: readonly Decision[] = [
179	  {
180	    id: "allergy_ticket",
181	    title: "Allergy ticket on the board",
182	    speaker: STAFF.supply_lead.name,
183	    speakerRole: "supply_lead",
184	    prompt: "Table 2 is a peanut allergy and the ticket is for fish. Mira wants to swap in the house sauce. How do we run it?",
185	    options: [
186	      {
187	        id: "verify",
188	        label: "Verify every plate with Mira",
189	        detail: "Costs one tick of kitchen time. The ticket is guaranteed safe and the guest notices the care.",
190	        tone: "safe",
191	      },
192	      {
193	        id: "substitute",
194	        label: "Let her substitute and send it",
195	        detail: "Fastest plate on the board. An unverified swap can put the guest in hospital — and end your night.",
196	        tone: "risky",
197	      },
198	      {
199	        id: "pull",
200	        label: "Pull the dish and comp the table",
201	        detail: "Zero risk. You eat the cost: −$22 and a small hit to satisfaction.",
202	        tone: "neutral",
203	      },
204	    ],
205	  },
206	  {
207	    id: "oven_down",
208	    title: "The oven just died",
209	    speaker: STAFF.chef.name,
210	    speakerRole: "chef",
211	    prompt: "Oven's dead with four tickets up. I can fix it or I can cook — not both.",
212	    options: [
213	      {
214	        id: "repair",
215	        label: "Get Mira on the oven",
216	        detail: "Kitchen off the line for two ticks, then the oven limps back. Tickets pile up meanwhile.",
