277	export const DECISIONS_BY_ID: ReadonlyMap<string, Decision> = new Map(DECISIONS.map((d) => [d.id, d]));
278	
279	/** `decide_<decision>_<option>` — one replayable action id per option. */
280	export type DecisionAction = `decide_${string}`;
281	
282	export const DECISION_ACTIONS: readonly DecisionAction[] = DECISIONS.flatMap((decision) =>
283	  decision.options.map((option) => `decide_${decision.id}_${option.id}` as DecisionAction),
284	);
285	
286	export function parseDecisionAction(action: string): { decisionId: string; optionId: string } | undefined {
287	  if (!action.startsWith("decide_")) return undefined;
288	  for (const decision of DECISIONS) {
289	    const prefix = `decide_${decision.id}_`;
290	    if (!action.startsWith(prefix)) continue;
291	    const optionId = action.slice(prefix.length);
292	    if (decision.options.some((option) => option.id === optionId)) return { decisionId: decision.id, optionId };
293	  }
294	  return undefined;
295	}
296	
297	export interface SimControl {
298	  /** False until the player starts the shift, so nothing moves on a cold open. */
299	  readonly started: boolean;
300	  readonly running: boolean;
301	  readonly speed: SimSpeed;
302	}
303	
304	export interface DebriefLine {
305	  readonly label: string;
306	  readonly value: string;
307	  readonly good: boolean;
308	}
309	
310	/**
311	 * One of the conditions tonight was actually judged on, with the number it
312	 * was judged against.
313	 *
314	 * `DebriefLine.good` is a colour hint tuned for reading a shift at a glance
315	 * ("walkouts ≤ 1 is a good night"), which is *not* the same bar as the
316	 * preset's goal ("≤ 2 walkouts passes"). Showing only those flags next to a
317	 * TARGET MET/MISSED verdict left the two silently disagreeing, so the target
318	 * checks are reported separately and explicitly.
319	 */
320	export interface DebriefTarget {
321	  readonly label: string;
322	  /** What the shift actually did. */
323	  readonly value: string;
324	  /** What it had to do — "≥ $190", "≤ 2". */
325	  readonly requirement: string;
326	  readonly met: boolean;
327	}
328	
329	export interface Debrief {
330	  readonly grade: string;
331	  readonly headline: string;
332	  /** Whether tonight's target was met. */
333	  readonly met: boolean;
334	  /** The conditions `met` was computed from, each with its own verdict. */
335	  readonly targets: readonly DebriefTarget[];
336	  readonly lines: readonly DebriefLine[];
337	  /** What to do differently — the reason to press restart. */
338	  readonly lessons: readonly string[];
339	}
340	
341	/**
342	 * What just happened as a direct result of the player's last decision — a
343	 * one-line receipt, shown as a brief on-canvas callout so the consequence
344	 * lands where the player is already looking (where the decision card was)
345	 * instead of only being legible by scrolling the service log. `id` changes
346	 * on every new decision answered (even a repeat of the same option), which
347	 * is how the scene tells "a fresh outcome just landed" from "the same one
348	 * is still in view".
349	 */
350	export interface DecisionOutcome {
351	  readonly id: string;
352	  readonly headline: string;
353	  readonly tone: DecisionTone;
354	}
355	
356	/**
357	 * Everything the overlay draws: the contract state plus the playable layer.
358	 * The scene renders from this and nothing else.
359	 */
360	export interface ArenaView extends RestaurantState {
361	  readonly sim: SimControl;
362	  readonly feed: readonly FeedEntry[];
363	  readonly waiting: readonly WaitingParty[];
364	  /** Open decision holding the clock, if any. */
365	  readonly decision?: Decision;
366	  /** The receipt for the most recently answered decision, if any yet. */
367	  readonly lastOutcome?: DecisionOutcome;
368	  readonly staff: Readonly<Record<Role, StaffProfile>>;
369	  readonly goal: ShiftGoal;
370	  /**
371	   * The two running counters the goal is judged on that `RestaurantState`
372	   * does not carry. Live, so the shift view can show how close the night is
373	   * to failing instead of only revealing it in the debrief.
374	   */
375	  readonly tally: { readonly walkouts: number; readonly unsafeServed: number };
376	  /** Which night is being worked, for the pre-shift card. */
377	  readonly shift: { id: string; title: string };
378	  /** Present only once the shift has ended. */
379	  readonly debrief?: Debrief;
380	  readonly timeline?: TimelineModel;
381	  readonly score: number;
382	  /** The one in-shift purchase currently on offer: cost, and whether it's bought. */
383	  readonly upgrade: { id: "second_stove"; label: string; cost: number; bought: boolean };
384	  /** Training-shift prompt. Absent on scored nights. */
385	  readonly coach?: CoachPrompt;
386	}
387	
388	export interface CoachPrompt {
389	  readonly step: number;
390	  readonly total: number;
391	  readonly title: string;
392	  readonly detail: string;
393	}
394	
395	const TUTORIAL_STEPS = 3;
396	
397	/**
398	 * The next thing a first-time player should do on the training shift.
399	 * Scored nights return nothing — a coach line on Dinner Rush would pollute
400	 * the decision surface the benchmark is measuring.
401	 */
402	export function tutorialCoach(view: {
403	  readonly shift: { id: string };
404	  readonly sim: SimControl;
405	  readonly workers: readonly { role: string; location: string }[];
406	  readonly orders: readonly { tableId?: string; status: string; allergy?: string; priority: string }[];
407	  readonly decision?: { id: string };
408	  readonly goal: ShiftGoal;
409	  /** Decision ids already answered this shift — so a resolved allergy call is not re-taught. */
410	  readonly decidedIds?: readonly string[];
411	}): CoachPrompt | undefined {
412	  if (view.shift.id !== TUTORIAL_SHIFT_ID) return undefined;
413	  if (!view.sim.started) {
414	    return {
415	      step: 0,
416	      total: TUTORIAL_STEPS,
417	      title: "Training shift",
418	      detail: "Read the target, then open the doors. Space starts and pauses the clock.",
419	    };
420	  }
421	  const hasRushed = view.orders.some((order) => order.priority === "high");
422	  if (!hasRushed) {
423	    const rushOrder =
424	      view.orders.find((order) => order.tableId === "table-1" && order.status !== "served" && order.status !== "cancelled") ??
425	      view.orders.find((order) => order.status !== "served" && order.status !== "cancelled" && !order.allergy && order.tableId?.match(/^table-[1-3]$/)) ??
426	      view.orders.find((order) => order.status !== "served" && order.status !== "cancelled" && !order.allergy);
427	    if (rushOrder) {
428	      const tableNum = (rushOrder.tableId?.match(/\d+/) ?? ["1"])[0];
429	      const tableLabel = rushOrder.tableId ? rushOrder.tableId.replace("table-", "table ") : "table 1";
430	      const isTable1 = rushOrder.tableId === "table-1";
431	      return {
432	        step: 1,
433	        total: TUTORIAL_STEPS,
434	        title: `Rush ${tableLabel}`,
435	        detail: isTable1
436	          ? "optional — click the pasta ticket (or press 1) to cook that table first"
437	          : `optional — click the ticket (or press ${tableNum}) to cook that table first`,
438	      };
439	    }
440	  }
441	  const allergyDecided = view.decidedIds?.includes("allergy_ticket") === true;
442	  if (!allergyDecided && view.decision?.id === "allergy_ticket") {
443	    return {
444	      step: 2,
445	      total: TUTORIAL_STEPS,
446	      title: "allergy call",
447	      detail: "clock is stopped — pick verify or one unchecked plate fails the night",
448	    };
449	  }
450	  const allergy = view.orders.find((order) => order.allergy && order.status !== "served" && order.status !== "cancelled");
451	  if (!allergyDecided && allergy) {
452	    return {
453	      step: 2,
454	      total: TUTORIAL_STEPS,
455	      title: "protect the allergy",
456	      detail: "click the allergy ticket or press v — one unchecked plate fails the night",
457	    };
458	  }
459	  return {
460	    step: 3,
461	    total: TUTORIAL_STEPS,
462	    title: "Hit the number",
463	    detail: `Take $${view.goal.cash} without an unsafe plate. HOLD the door if the queue piles up.`,
464	  };
465	}
