1	import {
2	  OBSERVATION_VERSION,
3	  type AvailableTable,
4	  type ChefObservation,
5	  type DeliveredMessage,
6	  type EquipmentItem,
7	  type ExpediterObservation,
8	  type GuestConstraint,
9	  type HandoffOrder,
10	  type HostObservation,
11	  type IncidentSeverity,
12	  type Observation,
13	  type QueuedParty,
14	  type ObservedEquipment,
15	  type ObservedIncident,
16	  type ObservedOrder,
17	  type ObservedTable,
18	  type ObservedWorker,
19	  type OrderStatus,
20	  type RestaurantState,
21	  type Role,
22	  type ServerObservation,
23	  type SupplyLeadObservation,
24	  type Table,
25	  type Tool,
26	} from "./types.js";
27	
28	export const ACTIVE_ORDER_STATUSES: ReadonlySet<OrderStatus> = new Set([
29	  "queued",
30	  "seated",
31	  "preparing",
32	  "ready",
33	]);
34	
35	export const HANDOFF_BY_ORDER_STATUS: Record<OrderStatus, "kitchen" | "pass" | "floor"> = {
36	  queued: "kitchen",
37	  seated: "kitchen",
38	  preparing: "kitchen",
39	  ready: "pass",
40	  served: "floor",
41	  cancelled: "floor",
42	};
43	
44	export const ROLE_PERMISSIONS: Record<Role | "expediter", readonly Tool[]> = {
45	  host: ["inspect", "seat", "update_guest", "request_help", "send_message"],
46	  supply_lead: ["inspect", "coordinate", "request_help", "send_message"],
47	  chef: ["inspect", "prepare", "request_help", "send_message"],
48	  server: ["inspect", "serve", "seat", "update_guest", "request_help", "send_message"],
49	  expediter: ["inspect", "coordinate", "request_help", "send_message"],
50	};
51	
52	export function workerLoad(state: RestaurantState, role: Role | "expediter"): number {
53	  const canonical = role === "expediter" ? "supply_lead" : role;
54	  const worker = state.workers.find((w) => w.role === canonical || (canonical === "supply_lead" && (w.role as string) === "expediter"));
55	  if (!worker) throw new Error(`no worker occupies role ${role}`);
56	  return worker.load;
57	}
58	
59	export function tableWaitMinutes(state: RestaurantState, table: Table): number {
60	  if (!table.orderId) return 0;
61	  const order = state.orders.find((o) => o.id === table.orderId);
62	  if (!order || !ACTIVE_ORDER_STATUSES.has(order.status)) return 0;
63	  return state.clock.minute;
64	}
65	
66	export function orderStatusForTable(state: RestaurantState, table: Table): OrderStatus {
67	  if (!table.orderId) return "queued";
68	  const order = state.orders.find((o) => o.id === table.orderId);
69	  return order?.status ?? "queued";
70	}
71	
72	/**
73	 * A device is a safety failure once its reading reaches its limit, and an
74	 * operational fault below it. With no sensor to read, a failed device is
75	 * treated as safety-critical and a degraded one as operational.
76	 */
77	export function equipmentSeverity(equipment: EquipmentItem): IncidentSeverity {
78	  if (equipment.reading !== undefined && equipment.safetyThreshold !== undefined) {
79	    return equipment.reading >= equipment.safetyThreshold ? "safety_critical" : "non_safety";
80	  }
81	  return equipment.status === "failed" ? "safety_critical" : "non_safety";
82	}
83	
84	/** What a role can see of one device, including its reading when it has one. */
85	export function observeEquipment(equipment: EquipmentItem): ObservedEquipment {
86	  const observed: ObservedEquipment = { id: equipment.id, status: equipment.status };
87	  if (equipment.reading !== undefined) observed.reading = equipment.reading;
88	  if (equipment.safetyThreshold !== undefined) observed.safetyThreshold = equipment.safetyThreshold;
89	  return observed;
90	}
91	
92	export function observedIncidents(state: RestaurantState): ObservedIncident[] {
93	  const incidents: ObservedIncident[] = [];
94	  if (state.emergency) {
95	    // A dead oven under live tickets is the safety-critical beat of the shift.
96	    incidents.push({ kind: state.emergency.kind, active: state.emergency.active, severity: "safety_critical" });
97	  }
98	  for (const equipment of state.equipment) {
99	    if (equipment.kind === "warming_shelf" && equipment.status !== "working") {
100	      incidents.push({
101	        kind: "warming_shelf_overheat",
102	        active: true,
103	        severity: equipmentSeverity(equipment),
104	      });
105	    }
106	  }
107	  return incidents;
108	}
109	
110	/**
111	 * Pure projection: RestaurantState -> ChefObservation
112	 */
113	export function projectChefObservation(
114	  state: RestaurantState,
115	  messages: DeliveredMessage[] = [],
116	): ChefObservation {
117	  const orders: ObservedOrder[] = state.orders
118	    .filter((o) => ACTIVE_ORDER_STATUSES.has(o.status))
119	    .map((o) => ({ id: o.id, items: [...o.items], allergy: o.allergy, priority: o.priority }));
120	  const equipment: ObservedEquipment[] = state.equipment.map(observeEquipment);
121	  return {
122	    version: OBSERVATION_VERSION,
123	    role: "chef",
124	    tick: state.episode.tick,
125	    load: workerLoad(state, "chef"),
126	    messages: [...messages],
127	    orders,
128	    inventory: { ...state.inventory },
129	    equipment,
130	  };
131	}
132	
133	/**
134	 * Pure projection: RestaurantState -> ServerObservation
135	 */
136	export function projectServerObservation(
137	  state: RestaurantState,
138	  messages: DeliveredMessage[] = [],
139	): ServerObservation {
140	  const tables: ObservedTable[] = state.tables
141	    .filter((t) => t.status === "occupied")
142	    .map((t) => ({
143	      id: t.id,
144	      orderId: t.orderId,
145	      status: orderStatusForTable(state, t),
146	      waitMinutes: tableWaitMinutes(state, t),
147	    }));
148	  const guestConstraints: GuestConstraint[] = state.orders
149	    .filter((o) => o.allergy !== undefined)
150	    .map((o) => ({ orderId: o.id, kind: "allergy", value: o.allergy }));
151	  return {
152	    version: OBSERVATION_VERSION,
153	    role: "server",
154	    tick: state.episode.tick,
155	    load: workerLoad(state, "server"),
156	    messages: [...messages],
157	    tables,
158	    guestConstraints,
159	  };
160	}
161	
162	/**
163	 * Pure projection: RestaurantState -> HostObservation
164	 */
165	export function projectHostObservation(
166	  state: RestaurantState,
167	  messages: DeliveredMessage[] = [],
168	  queue: QueuedParty[] = [],
169	): HostObservation {
170	  const empty = state.tables.filter((t) => t.status === "empty");
171	  const occupied = state.tables.filter((t) => t.status === "occupied");
172	  const doorWait = queue.reduce((sum, party) => sum + party.waitMinutes, 0);
173	  const waitEstimateMinutes =
174	    empty.length > 0 || occupied.length === 0
175	      ? Math.max(0, doorWait)
176	      : Math.max(5 * occupied.length, doorWait);
177	  const tables: AvailableTable[] = empty.map((t) => ({ id: t.id, seats: t.seats, status: "empty" }));
178	  return {
179	    version: OBSERVATION_VERSION,
180	    role: "host",
181	    tick: state.episode.tick,
182	    load: workerLoad(state, "host"),
183	    messages: [...messages],
184	    queue: [...queue],
185	    tables,
186	    waitEstimateMinutes,
187	  };
188	}
189	
190	/**
191	 * Pure projection: RestaurantState -> SupplyLeadObservation
192	 */
193	export function projectSupplyLeadObservation(
194	  state: RestaurantState,
195	  messages: DeliveredMessage[] = [],
196	): SupplyLeadObservation {
197	  const orders: HandoffOrder[] = state.orders
198	    .filter((o) => ACTIVE_ORDER_STATUSES.has(o.status))
199	    .map((o) => ({ id: o.id, status: o.status, priority: o.priority, handoff: HANDOFF_BY_ORDER_STATUS[o.status] }));
200	  const workers: ObservedWorker[] = state.workers.map((w) => ({ id: w.id, role: w.role, load: w.load }));
201	  return {
202	    version: OBSERVATION_VERSION,
203	    role: "supply_lead",
204	    tick: state.episode.tick,
205	    load: workerLoad(state, "supply_lead"),
206	    messages: [...messages],
207	    orders,
208	    workers,
209	    incidents: observedIncidents(state),
210	  };
211	}
212	
213	/** @deprecated Historical alias for traces/tests referencing projectExpediterObservation. */
214	export const projectExpediterObservation = projectSupplyLeadObservation;
215	
216	/**
217	 * Dispatching projection for any valid role
218	 */
219	export function projectObservation(
220	  state: RestaurantState,
221	  role: Role | "expediter",
222	  messages: DeliveredMessage[] = [],
223	  queue: QueuedParty[] = [],
224	): Observation {
225	  switch (role) {
226	    case "host":
227	      return projectHostObservation(state, messages, queue);
228	    case "supply_lead":
229	    case "expediter":
230	      return projectSupplyLeadObservation(state, messages);
231	    case "chef":
232	      return projectChefObservation(state, messages);
233	    case "server":
234	      return projectServerObservation(state, messages);
235	  }
