219	export function projectObservation(
220	  state: RestaurantState,
221	  role: Role | "expediter",
222	  messages: DeliveredMessage[] = [],
223	  queue: QueuedParty[] = [],
224	): Observation {
225	  switch (role) {
226	    case "host":
227	      return projectHostObservation(state, messages, queue);
228	    case "supply_lead":
229	    case "expediter":
230	      return projectSupplyLeadObservation(state, messages);
231	    case "chef":
232	      return projectChefObservation(state, messages);
233	    case "server":
234	      return projectServerObservation(state, messages);
235	  }
236	}
