453	function escapeXml(str: string): string {
454	  return str
455	    .replace(/&/g, "&amp;")
456	    .replace(/</g, "&lt;")
457	    .replace(/>/g, "&gt;")
458	    .replace(/"/g, "&quot;")
459	    .replace(/'/g, "&apos;");
460	}
