arguments.new_string:
if (envelope.tool === "correct") {
  const note = envelope.arguments.note as string | undefined;
  if (typeof note !== "string" || !note.trim()) {
    const err: ActionError = { code: "invalid_arguments", message: "correct requires non-empty string 'note'", retryable: false };
    const res = { accepted: false, state: this.state(), error: err };
    this.idempotencyCache.set(envelope.idempotencyKey, res);
    return res;
  }
  // `lift: "dir-1"` is the only way a correction stops binding. Rejecting
  // an id that is not standing keeps the manager from believing they
  // released a floor that is still under the rule.
  const lift = envelope.arguments.lift;
  if (lift !== undefined) {
    if (typeof lift !== "string" || !lift.trim()) {
      const err: ActionError = { code: "invalid_arguments", message: "correct 'lift' must be a standing correction id", retryable: false };
      const res = { accepted: false, state: this.state(), error: err };
      this.idempotencyCache.set(envelope.idempotencyKey, res);
      return res;
    }
    const lifted = this.liftDirective(lift);
    if (!lifted) {
      const err: ActionError = { code: "unknown_entity", message: `no standing correction ${lift}`, retryable: false };
      const res = { accepted: false, state: this.state(), error: err };
      this.idempotencyCache.set(envelope.idempotencyKey, res);
      return res;
    }
    if (lifted.rule === "hold_the_door") this.currentState.seatingHeld = false;
    this.log("you", "player", note);
    this.log(lifted.roles[0] ?? "house", "action", `Understood — ${lifted.id} is lifted.`);
  } else {
    this.applySafetyCorrection(note, this.correctionTargetRole(envelope));
  }
}

