2752	    // The round's envelope is spent, so this one does not land. Recording the
2753	    // refusal rather than dropping it is the point: a manager who tried twice
2754	    // in one round is a different session from one who acted once, and the
2755	    // trace has to be able to tell them apart.
2756	    if (!answersOpenDecision && !this.roundStatus().canAct) {
2757	      const denial: ActionError = this.isOver()
2758	        ? { code: "episode_complete", message: "the shift is over", retryable: false }
2759	        : {
2760	            code: "round_budget_exhausted",
2761	            message: `round ${this.roundNumber} already spent its manager envelope; wait for round ${this.roundNumber + 1}`,
2762	            retryable: false,
2763	          };
2764	      this.recordEvent({
2765	        tick: base.tick,
2766	        kind: "action",
2767	        timestamp: base.timestamp,
2768	        stateHash: computeStateHash({ episodeId: base.episodeId, rejected: input.kind, tick: base.tick, round: this.roundNumber }),
2769	        actorId: "player",
2770	        requestId,
2771	        action: { tool: "rejected", arguments: { kind: input.kind, targetRole } },
2772	        toolResult: { ok: false, error: { code: denial.code, message: denial.message, retryable: denial.retryable } },
2773	      });
2774	      return { accepted: false, state: this.state(), error: denial };
2775	    }
2776	
2777	    let envelope: ActionEnvelope;
2778	    switch (input.kind) {
2779	      case "message":
2780	        if (typeof input.text !== "string" || !input.text.trim()) return reject("message requires non-empty text");
2781	        if (input.text.length > 256) return reject("message text cannot exceed 256 characters");
2782	        if (input.targetRole === "everyone") {
2783	          const targets = this.currentState.workers;
2784	          if (targets.length === 0) return reject("no workers are available");
2785	          let result: { accepted: boolean; state: RestaurantState; error?: ActionError } = { accepted: true, state: this.state() };
2786	          for (const target of targets) {
2787	            result = this.stepEnvelope({
2788	              ...base,
2789	              role: target.role,
2790	              requestId: `${requestId}-${target.role}`,
2791	              idempotencyKey: `${base.idempotencyKey}-${target.role}`,
2792	              tool: "send_message",
2793	              arguments: { to: target.id, text: input.text, priority: input.priority ?? "normal" },
