14	
15	export type ObservationFormat = "markdown" | "json" | "xml";
16	export type RoleTone = "professional" | "concise" | "collaborative";
17	
18	export interface PromptBuilderOptions {
19	  /** Serialized observation style in turn prompts (default: "markdown") */
20	  format?: ObservationFormat;
21	  /** Tone of role persona instructions (default: "professional") */
22	  tone?: RoleTone;
23	  /** Whether to append curated few-shot decision examples (default: true) */
24	  includeFewShot?: boolean;
25	  /** Whether to list permitted tool schemas & argument details (default: true) */
26	  includeTools?: boolean;
27	}
28	
29	export interface FewShotExample {
30	  title: string;
31	  situation: string;
32	  observationSummary: string;
33	  reasoning: string;
34	  action: {
35	    tool: Tool;
36	    arguments: Record<string, unknown>;
37	  };
38	}
