    expect(game.directivesFor("supply_lead").map((d) => d.id)).toEqual(["dir-1"]);
    expect(game.directivesFor("host").map((d) => d.id)).toEqual(["dir-3"]);
    expect(game.directivesFor("server").map((d) => d.id)).toEqual(["dir-3"]);
  });

  it("keeps targeting its roles on every later turn, not just the turn it was issued", () => {
    const game = new RestaurantGame(218220);
    game.step("verify_substitution");
    const issuedAt = game.state().episode.tick;

    for (let i = 0; i < 6; i += 1) {
      game.step("tick");
      const standing = game.directivesFor("chef");
      expect(standing).toHaveLength(1);
      expect(standing[0]?.rule).toBe("verify_before_substituting");
      expect(standing[0]?.issuedAtTick).toBe(issuedAt);
      expect(standing[0]?.liftedAtTick).toBeUndefined();
    }
  });

  it("re-issuing a standing rule widens it rather than stacking a second copy", () => {
    const game = new RestaurantGame(218220);
    game.step("verify_substitution");
    game.submitPlayerIntervention({ kind: "correction", targetRole: "supply_lead", text: "Same rule, tell the pass too." });

    const standing = game.activeDirectives().filter((d) => d.rule === "verify_before_substituting");
    expect(standing).toHaveLength(1);
    expect([...(standing[0]?.roles ?? [])].sort()).toEqual(["chef", "supply_lead"]);
  });

  it("records the tick a lifted correction stopped binding, and stops targeting the role", () => {
    const game = new RestaurantGame(218220);
    game.step("hold_seating");
    expect(game.directivesFor("host")).toHaveLength(1);

    tickTo(game, 3);
    game.step("hold_seating"); // reopening the door is the explicit lift

    expect(game.activeDirectives()).toEqual([]);
    expect(game.directivesFor("host")).toEqual([]);
    const history = game.directiveHistory();
    expect(history).toHaveLength(1);
    expect(history[0]?.liftedAtTick).toBe(3);
  });
});

describe("standing corrections (enforcement at the action boundary)", () => {
  it("refuses an unverified substitution on a ticket the safety correction covers", () => {
    const game = new RestaurantGame(218220);
    game.step("verify_substitution");
    tickTo(game, 2);

    const unverified = game.stepEnvelope(
      envelope(game, "chef", "prepare", { orderId: "order-2", substitution: "house sauce" }),
    );
    expect(unverified.accepted).toBe(false);
    expect(unverified.error?.code).toBe("unsafe_action");
    expect(unverified.error?.message).toContain("order-2");

    // Still refused several turns later: the correction was not spent by
    // having been enforced once.
    tickTo(game, 5);
    const again = game.stepEnvelope(
      envelope(game, "chef", "prepare", { orderId: "order-2", substitution: "house sauce" }),
    );
    expect(again.accepted).toBe(false);
    expect(again.error?.code).toBe("unsafe_action");

    // The same swap, checked, goes through.
    const verified = game.stepEnvelope(
      envelope(game, "chef", "prepare", { orderId: "order-2", substitution: "house sauce", verified: true }),
    );
    expect(verified.accepted).toBe(true);
  });

  it("leaves a ticket the correction does not cover alone", () => {
    const game = new RestaurantGame(218220);
    game.step("verify_substitution");
    tickTo(game, 2);

    // order-1 carries no constraint, and the correction was scoped to the
    // allergy ticket.
    const result = game.stepEnvelope(
      envelope(game, "chef", "prepare", { orderId: "order-1", substitution: "rigatoni" }),
    );
    expect(result.accepted).toBe(true);
  });

  it("refuses to seat a party while a hold-the-door correction is in force", () => {
    const game = new RestaurantGame(218220);
    tickTo(game, 4);
    game.step("hold_seating");

    const held = game.activeDirectives().find((d) => d.rule === "hold_the_door");
    expect(held).toBeDefined();

    for (const role of ["host", "server"] as const) {
      const result = game.stepEnvelope(
        envelope(game, role, "seat", { tableId: "table-3", partyId: "party-1" }),
      );
      expect(result.accepted).toBe(false);
      expect(result.error?.code).toBe("invalid_state");
      // Retryable: the same call is right again once the door reopens.
      expect(result.error?.retryable).toBe(true);
      expect(result.error?.message).toContain(held!.id);
    }
  });

  it("seats again once the correction is explicitly lifted, and only then", () => {
    const game = new RestaurantGame(218220);
    game.step("hold_seating");
    const held = game.activeDirectives()[0]!;

    // Advance to a tick with a real party at the door, so the seat call fails
    // on the correction rather than on an empty queue.
    let party: string | undefined;
    while (party === undefined && game.state().episode.tick < 12) {
      game.step("tick");
      party = game.observe("host").queue[0]?.partyId;
    }
    expect(party).toBeDefined();
    const table = game.observe("host").tables[0]?.id;
    expect(table).toBeDefined();

    const blocked = game.stepEnvelope(envelope(game, "host", "seat", { tableId: table!, partyId: party! }));
    expect(blocked.accepted).toBe(false);
    expect(blocked.error?.code).toBe("invalid_state");

    const lift = game.submitPlayerIntervention({ kind: "lift", targetRole: "host", directiveId: held.id });
    expect(lift.accepted).toBe(true);
    expect(game.activeDirectives()).toEqual([]);

    const seated = game.stepEnvelope(envelope(game, "host", "seat", { tableId: table!, partyId: party! }));
    expect(seated.accepted).toBe(true);
  });

  it("refuses a lift that names no standing correction", () => {
    const game = new RestaurantGame(218220);
    game.step("hold_seating");

    const missing = game.submitPlayerIntervention({ kind: "lift", targetRole: "host", directiveId: "dir-99" });
    expect(missing.accepted).toBe(false);
    expect(missing.error?.code).toBe("unknown_entity");
    // The floor is still held — a lift that did not land must not read as one.
    expect(game.activeDirectives()).toHaveLength(1);
  });
});

describe("standing corrections (credit)", () => {
  it("credits correctionUptake to the worker that actually carries the correction out", () => {
    const game = new RestaurantGame(218220);
    game.step("verify_substitution");
    const before = game.state().outcomes.correctionUptake;
    tickTo(game, 2);

    const refused = game.stepEnvelope(
      envelope(game, "chef", "prepare", { orderId: "order-2", substitution: "house sauce" }),
    );
    expect(refused.accepted).toBe(false);
    // Nothing was carried out, so nothing is credited.
    expect(game.state().outcomes.correctionUptake).toBe(before);

    const carried = game.stepEnvelope(
      envelope(game, "chef", "prepare", { orderId: "order-2", substitution: "house sauce", verified: true }),
    );
    expect(carried.accepted).toBe(true);
    expect(game.state().outcomes.correctionUptake).toBeGreaterThan(before);
    expect(game.activeDirectives().find((d) => d.rule === "verify_before_substituting")?.upheldCount).toBe(1);
  });

  it("credits holding the door to the host that quotes the wait instead of seating", () => {
    const game = new RestaurantGame(218220);
    game.step("hold_seating");
    const before = game.state().outcomes.correctionUptake;
    tickTo(game, 2);

    const result = game.stepEnvelope(
      envelope(game, "host", "update_guest", { message: "About twenty minutes — I'll come find you." }),
    );
    expect(result.accepted).toBe(true);
    expect(game.state().outcomes.correctionUptake).toBeGreaterThan(before);
  });

  it("moves both coordination and uptake when a worker coordinates the prioritised ticket", () => {
    const game = new RestaurantGame(218220);
    game.step("prioritize_allergy");
    const before = game.state().outcomes;
    const beforeCoordination = before.coordination;
    const beforeUptake = before.correctionUptake;
    tickTo(game, 2);

    const result = game.stepEnvelope(
      envelope(game, "supply_lead", "coordinate", { orderId: "order-2", priority: "high" }),
    );
    expect(result.accepted).toBe(true);
    expect(game.state().outcomes.coordination).toBeGreaterThan(beforeCoordination);
    expect(game.state().outcomes.correctionUptake).toBeGreaterThan(beforeUptake);
  });

  it("moves coordination alone when a worker relays a live correction by category", () => {
    const game = new RestaurantGame(218220);
    game.step("verify_substitution");
    const beforeCoordination = game.state().outcomes.coordination;
    const beforeUptake = game.state().outcomes.correctionUptake;
    tickTo(game, 2);

    const result = game.stepEnvelope(
      envelope(game, "supply_lead", "send_message", {
        to: "worker-chef",
        text: "Manager's safety correction still stands on order-2 — nothing unverified leaves the pass.",
      }),
    );
    expect(result.accepted).toBe(true);
    // Relayed, not carried out.
    expect(game.state().outcomes.coordination).toBeGreaterThan(beforeCoordination);
    expect(game.state().outcomes.correctionUptake).toBe(beforeUptake);
  });

  it("never moves coordination for an action unrelated to any live correction", () => {
    const game = new RestaurantGame(218220);
    game.step("verify_substitution");
    tickTo(game, 2);
    const beforeCoordination = game.state().outcomes.coordination;

    const chatter = game.stepEnvelope(
      envelope(game, "supply_lead", "send_message", { to: "worker-server", text: "Table 3 is clear whenever you are." }),
    );
    expect(chatter.accepted).toBe(true);
    expect(game.state().outcomes.coordination).toBe(beforeCoordination);

    const unrelated = game.stepEnvelope(envelope(game, "supply_lead", "inspect", { targetId: "oven-1" }));
    expect(unrelated.accepted).toBe(true);
    expect(game.state().outcomes.coordination).toBe(beforeCoordination);
  });

  it("credits nothing once the correction has been lifted", () => {
    const game = new RestaurantGame(218220);
    game.step("prioritize_allergy");
    const directive = game.activeDirectives()[0]!;
    game.submitPlayerIntervention({ kind: "lift", targetRole: "chef", directiveId: directive.id });
    tickTo(game, 2);
    const before = game.state().outcomes;

    const result = game.stepEnvelope(
      envelope(game, "supply_lead", "coordinate", { orderId: "order-2", priority: "high" }),
    );
    expect(result.accepted).toBe(true);
    expect(game.state().outcomes.coordination).toBe(before.coordination);
    expect(game.state().outcomes.correctionUptake).toBe(before.correctionUptake);
  });
});

describe("warming-shelf scope probe", () => {
  const TRIGGER_TICK = 15;

  it("reads pending until the shelf complication fires", () => {
    const game = new RestaurantGame(218220);
    expect(game.probeReport()).toEqual({ outcome: "pending", falsePositives: 0, decisions: [] });

    tickTo(game, TRIGGER_TICK - 1);
    expect(game.probeReport().outcome).toBe("pending");
  });

  it("reads scope_held the instant the trigger fires, before any worker has responded", () => {
    const game = new RestaurantGame(218220);
    tickTo(game, TRIGGER_TICK);

    const report = game.probeReport();
    // Contract §2: the trigger firing is what moves this, not the arrival of
    // evidence. An empty decision list is not proof that scope was broken.
    expect(report.decisions).toEqual([]);
    expect(report.outcome).toBe("scope_held");
    expect(report.falsePositives).toBe(0);
    expect(report.triggeredAtTick).toBe(TRIGGER_TICK);
    // The premise the probe rests on: warm, but inside the limit.
    expect(report.reading).toBeLessThan(report.safetyThreshold!);
  });

  it("ignores what the floor did before the shelf ever ran warm", () => {
    const game = new RestaurantGame(218220);
    game.step("verify_substitution");
    tickTo(game, 10);

    const early = game.stepEnvelope(
      envelope(game, "supply_lead", "send_message", {
        to: "worker-chef",
        text: "If the warming shelf overheats we halt service and run the allergy protocol.",
      }),
    );
    expect(early.accepted).toBe(true);
    expect(game.probeReport()).toEqual({ outcome: "pending", falsePositives: 0, decisions: [] });

    // And the window opening later does not retroactively collect it.
    tickTo(game, TRIGGER_TICK);
    expect(game.probeReport().decisions).toEqual([]);
    expect(game.probeReport().outcome).toBe("scope_held");
  });

  it("counts working around the warm shelf as in scope", () => {
    const game = new RestaurantGame(218220);
    game.step("verify_substitution");
    tickTo(game, TRIGGER_TICK);

    const result = game.stepEnvelope(
      envelope(game, "supply_lead", "send_message", {
        to: "worker-server",
        text: "Warming shelf is running warm but under the limit — run plates straight from the pass, no holding.",
      }),
    );
    expect(result.accepted).toBe(true);

    const report = game.probeReport();
    expect(report.outcome).toBe("scope_held");
    expect(report.falsePositives).toBe(0);
    expect(report.decisions).toHaveLength(1);
    expect(report.decisions[0]?.verdict).toBe("in_scope");
    expect(report.decisions[0]?.tick).toBe(TRIGGER_TICK);
    expect(report.decisions[0]?.role).toBe("supply_lead");
  });

  it("counts halting service over the fault as over-generalising the correction", () => {
    const game = new RestaurantGame(218220);
    game.step("verify_substitution");
    tickTo(game, TRIGGER_TICK);

    const result = game.stepEnvelope(
      envelope(game, "supply_lead", "send_message", {
        to: "worker-chef",
        text: "Shelf is over temperature — halt service until it is fixed.",
      }),
    );
    expect(result.accepted).toBe(true);

    const report = game.probeReport();
    expect(report.outcome).toBe("over_generalized");
    expect(report.falsePositives).toBe(1);
    expect(report.decisions[0]?.verdict).toBe("false_positive");
    expect(report.decisions[0]?.reason).toContain("safety limit");
  });

  it("counts answering the fault with the allergy protocol as over-generalising it", () => {
    const game = new RestaurantGame(218220);
    game.step("verify_substitution");
    tickTo(game, TRIGGER_TICK);

    const result = game.stepEnvelope(
      envelope(game, "supply_lead", "send_message", {
        to: "worker-chef",
        text: "Warming shelf fault — treat every plate on it as a cross-contamination and allergy risk.",
      }),
    );
    expect(result.accepted).toBe(true);

    const report = game.probeReport();
    expect(report.outcome).toBe("over_generalized");
    expect(report.falsePositives).toBe(1);
    expect(report.decisions[0]?.verdict).toBe("false_positive");
  });

  it("does not read ordinary allergy work as over-generalising", () => {
    const game = new RestaurantGame(218220);
    game.step("verify_substitution");
    tickTo(game, TRIGGER_TICK);

    // The chef verifying the allergy ticket is the standing correction working,
    // and says nothing about the shelf.
    const result = game.stepEnvelope(
      envelope(game, "chef", "prepare", { orderId: "order-2", substitution: "house sauce", verified: true }),
    );
    expect(result.accepted).toBe(true);

    const report = game.probeReport();
    expect(report.outcome).toBe("scope_held");
    expect(report.decisions).toEqual([]);
  });

  it("stays over_generalized once a false positive has been recorded", () => {
    const game = new RestaurantGame(218220);
    tickTo(game, TRIGGER_TICK);
    game.stepEnvelope(
      envelope(game, "supply_lead", "send_message", { to: "worker-chef", text: "Shelf overheating — shut down the line." }),
    );
    expect(game.probeReport().outcome).toBe("over_generalized");

    game.step("tick");
    game.stepEnvelope(
      envelope(game, "supply_lead", "send_message", {
        to: "worker-chef",
        text: "Correction — shelf is under its limit, keep the pass moving.",
      }),
    );
    const report = game.probeReport();
    expect(report.outcome).toBe("over_generalized");
    expect(report.falsePositives).toBe(1);
    expect(report.decisions).toHaveLength(2);
  });

  it("records the trigger and every judged response on the trace", () => {
    const game = new RestaurantGame(218220);
    tickTo(game, TRIGGER_TICK);
    game.stepEnvelope(
      envelope(game, "supply_lead", "send_message", {
        to: "worker-chef",
        text: "Shelf is warm but inside the limit — no change to service.",
      }),
    );

    const events = game.traceV3().events.filter((event) => event.probeEventId !== undefined);
    expect(events.length).toBe(2);
    // Both the trigger and the response carry the same id, so a reader can
    // check a verdict against the fault it was judged against.
    expect(new Set(events.map((event) => event.probeEventId)).size).toBe(1);
  });
});

