it("renders standing corrections in issue order, with the scope warning", () => {
  const turn = buildRoleTurnPrompt(chefObs, {
    directives: [
      {
        id: "dir-1",
        rule: "verify_before_substituting",
        category: "safety",
        note: "Verify before substituting.",
        issuedAtTick: 8,
        roles: ["chef"],
        orderIds: ["order-2"],
        upheldCount: 0,
      },
      {
        id: "dir-2",
        rule: "ticket_first",
        category: "priority",
        note: "Allergy ticket first.",
        issuedAtTick: 10,
        roles: ["chef"],
        orderIds: ["order-2"],
        upheldCount: 0,
      },
    ],
  });

  expect(turn).toContain("## Standing Corrections In Force");
  expect(turn).toContain("[SAFETY] dir-1 since tick 8 — Verify before substituting. (covers order-2)");
  expect(turn.indexOf("dir-1")).toBeLessThan(turn.indexOf("dir-2"));
  expect(turn).toContain("until the manager explicitly lifts it");
  // Both halves of the lesson: stretching a correction fails too.
  expect(turn).toContain("is as much a failure as ignoring the correction");
});

