describe("standing corrections (replay)", () => {
  it("reproduces the corrections and the probe window on replay", () => {
    const game = new RestaurantGame(218220);
    game.step("verify_substitution");
    game.stepEnvelope(envelope(game, "chef", "prepare", { orderId: "order-2", substitution: "house sauce" }));
    tickTo(game, 4);
    game.step("hold_seating");
    tickTo(game, 16);

    const replayed = replayArenaTrace(game.captureTrace({ runKind: "synthetic" }));

    // Standing corrections and the probe window both decide whether a later
    // action is allowed, so they have to survive a replay or the two runs could
    // diverge while still matching every checkpoint.
    expect(replayed.checkpointState()).toEqual(game.checkpointState());
    expect(replayed.activeDirectives()).toEqual(game.activeDirectives());
    expect(replayed.probeReport()).toEqual(game.probeReport());
  });
});

